    int a[] = {4, 2, 3, 1};
    int n = sizeof a / sizeof a[0];
    for (int i = 1; i < n; i++) {
        int key = a[i];
        int j = i - 1;
        while (j >= 0 && a[j] > key) {
            a[j + 1] = a[j];
            j--;
        }
